pub(crate) fn drain<T:RetireOwned>(value:T,bank:&mut Bank){let mut retirement_actual=None;let mut retirement_work=0;let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native field fixture supports paid close"));for _ in 0..10000{if owner.terminal_is_empty()&&retirement_actual.is_none(){return}assert!(owner.next_computational_work(bank.grant().maximum_copy_bytes).unwrap()<=bank.work);let result={let turn=crate::source_fixture::close_step(&mut retirement_actual,bank.grant(),bank.work,owner.next_demand(4096),owner.next_computational_work(4096),|g,a|{let result=owner.step(g,a);crate::RetainedWorkOutcome{result,work:owner.last_turn_work()}});retirement_work=turn.work;turn.result};let work=retirement_work;bank.step(RetainedWorkOutcome{result,work}).unwrap();}panic!("native field cleanup stalled")}
