fn denied(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut rows=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{rows.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})}if d.capacity_bytes>0{rows.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})}if d.release_bytes>0{rows.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g})}if d.depth>0{rows.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g})}rows}
#[test]fn native_receive_original_row_has_funded_fields_and_every_cancellation_frontier(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let mut observed=0;
 for cut in 0..128{let mut bank=Bank::new();let original=source(input(),&mut bank);let foreign=source(input(),&mut bank);let mut receiver=Row::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut turns=0;
  while turns<cut&&!receiver.output_ready(){let d=receiver.demands(original.borrow(),4096,bank.work).unwrap();let g=bank.grant();if turns>0{assert!(receiver.demands(foreign.borrow(),4096,bank.work).is_err())}for denied in denied(g,d){let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance(&mut receiver,original.borrow(),&mut control,denied,crate::source_fixture::WorkLoan::new(&bank.work,bank.work)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(original.borrow(),4096,bank.work).unwrap(),d);}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance(&mut receiver,original.borrow(),&mut control,g,crate::source_fixture::WorkLoan::new(&bank.work,bank.work)));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.normal(turn).unwrap();turns+=1;}
  if receiver.output_ready(){observed=turns;let row=take_row(&mut receiver,&mut bank);assert_eq!(row.id.as_str(),law["expected"]["id"].as_str().unwrap());assert_eq!(row.name.as_str(),law["expected"]["name"].as_str().unwrap());assert_eq!(row.value,law["expected"]["value"].as_i64().unwrap());assert_eq!(serde_json::json!({"id":row.id.as_str(),"name":row.name.as_str(),"value":row.value}),law["expected"]);drain(row,&mut bank);}close_receiver(&mut receiver,&mut bank);drain(original,&mut bank);drain(foreign,&mut bank);if observed>0&&cut>observed{break}
 }assert!(observed>0);
}
#[test]fn native_receive_constructor_and_output_denials_preserve_exact_owner(){
 let mut bank=Bank::new();let original=source(input(),&mut bank);let mut slot=tree::NativeReceiveSlot::<DslValue,Row>::default();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let original_pointer=original.borrow().get()as*const DslValue;let d=slot.demands(original.borrow(),4096,bank.work).unwrap();assert!(d.capacity_bytes>0);let g=bank.grant();for denied in denied(g,d){let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{let maximum=bank.work;let grant=denied;crate::source_fixture::receive(&mut control,grant,crate::source_fixture::WorkLoan::new(&maximum,maximum),|control|{let maximum=control.available_work_units().unwrap();slot.advance(original.borrow(),control,4096,maximum,grant)})});assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(slot.demands(original.borrow(),4096,bank.work).unwrap(),d);assert_eq!(original.borrow().get()as*const DslValue,original_pointer);}slot.begin_close().unwrap();assert!(slot.terminal_is_empty());
 let mut receiver=Row::receiver();for _ in 0..1000{if receiver.output_ready(){break}let turn=advance(&mut receiver,original.borrow(),&mut control,bank.grant(),crate::source_fixture::WorkLoan::new(&bank.work,bank.work));bank.normal(turn).unwrap();}assert!(receiver.output_ready());let pointer=receiver.output.as_ref().unwrap().id.get().as_ptr();let d=receiver.take_demand().unwrap();let g=bank.grant();for denied in denied(g,d){let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.take(denied));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));assert!(receiver.output_ready());assert_eq!(receiver.output.as_ref().unwrap().id.get().as_ptr(),pointer);}let row=take_row(&mut receiver,&mut bank);assert_eq!(row.id.get().as_ptr(),pointer);drain(row,&mut bank);close_receiver(&mut receiver,&mut bank);drain(original,&mut bank);
}
#[test]fn native_receive_domain_and_original_callback_refusals_keep_all_partial_custody(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/📐️.json")).unwrap();let entries=law["refusedEntries"].as_array().unwrap().iter().map(|pair|(pair[0].as_str().unwrap().to_owned(),if let Some(value)=pair[1].as_str(){DslValue::String(value.to_owned())}else{DslValue::Number(crate::Number::Int(pair[1].as_i64().unwrap()))})).collect();let mut bank=Bank::new();let original=source(DslValue::Object(entries),&mut bank);let mut receiver=Row::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut refused=false;for _ in 0..16{let turn=advance(&mut receiver,original.borrow(),&mut control,bank.grant(),crate::source_fixture::WorkLoan::new(&bank.work,bank.work));if bank.normal(turn).is_err(){refused=true;break}}assert!(refused);assert!(!receiver.output_ready());let DslValue::Object(entries)=original.borrow().get()else{panic!("original object changed")};assert_eq!(entries[0].0,entries[1].0);close_receiver(&mut receiver,&mut bank);drain(original,&mut bank);
 let original=source(input(),&mut bank);let mut receiver=Row::receiver();let admitted=std::cell::Cell::new(true);let mut callback=|_|admitted.get();let mut control=NativeDecodeControl::new(1<<20,&mut callback);for _ in 0..1000{if receiver.phase==3{break}let turn=advance(&mut receiver,original.borrow(),&mut control,bank.grant(),crate::source_fixture::WorkLoan::new(&bank.work,bank.work));bank.normal(turn).unwrap();}assert_eq!(receiver.phase,3);assert!(receiver.fields[0].ready());admitted.set(false);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance(&mut receiver,original.borrow(),&mut control,bank.grant(),crate::source_fixture::WorkLoan::new(&bank.work,bank.work)));assert_eq!(turn.work,0);assert!(bank.normal(turn).is_err());assert_eq!(heap,(0,0));assert!(receiver.fields[0].ready());assert!(!receiver.output_ready());close_receiver(&mut receiver,&mut bank);drain(original,&mut bank);
}
#[test]fn fixed_array_native_default_repeats_the_scalar_default_only_under_its_own_grant(){
 let mut bank=Bank::new();let mut header=None;let grant=bank.grant();let(turn,heap)=crate::observe_retirement_allocations(||<[f64;3]as NativeDefault>::default_cursor(&mut header,grant,None));let p=turn.result.unwrap().progress();assert_eq!(heap,(0,0));assert_eq!(p.copied_bytes,std::mem::size_of::<Option<<[f64;3]as NativeDefault>::Cursor>>());bank.post(p,turn.work);let mut cursor=header.take().unwrap();bank.post(RetainedCloneProgress{copied_items:1,..Default::default()},1);
 let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let d=cursor.demands(4096,bank.work).unwrap();let denied=RetainedCloneGrant::default();let turn=crate::source_fixture::receive(&mut control,denied,bank.work_loan(bank.work),|native|{let maximum=native.available_work_units().unwrap();cursor.advance(native,4096,maximum,denied)});assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(cursor.demands(4096,bank.work).unwrap(),d);
 for _ in 0..10000{if cursor.output_ready(){break}let maximum=bank.work;let d=cursor.demands(4096,maximum).unwrap();let g=bank.grant();let turn=crate::source_fixture::receive(&mut control,g,bank.work_loan(maximum),|native|cursor.advance(native,4096,maximum,g));let p=turn.result.as_ref().unwrap().progress();assert_eq!(p.copied_bytes,d.copy_bytes);bank.normal(turn).unwrap();}
 assert!(cursor.output_ready());let turn=cursor.take(bank.grant());let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();assert_eq!(p.copied_bytes,0);bank.post(p,turn.work);let(value,_)=turn.result.unwrap().unwrap();assert_eq!(value,[0.0;3]);drain(value,&mut bank);cursor.begin_close().unwrap();let mut actual=None;
 for _ in 0..10000{if cursor.terminal_is_empty()&&actual.is_none(){break}let turn=crate::source_fixture::close_step(&mut actual,bank.grant(),bank.work,cursor.close_demands(4096),cursor.close_work_demand(4096),|g,a|cursor.close_step(g,a));bank.step(turn).unwrap();}assert!(cursor.terminal_is_empty());
 let mut empty_header=None;let turn=<[u8;0]as NativeDefault>::default_cursor(&mut empty_header,bank.grant(),None);bank.step(turn).unwrap();let mut empty=empty_header.take().unwrap();bank.post(RetainedCloneProgress{copied_items:1,..Default::default()},1);
 let g=bank.grant();let turn=crate::source_fixture::receive(&mut control,g,bank.work_loan(0),|native|empty.advance(native,4096,0,g));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert!(!empty.output_ready());
 for _ in 0..10000{if empty.output_ready(){break}let g=bank.grant();let maximum=bank.work;let turn=crate::source_fixture::receive(&mut control,g,bank.work_loan(maximum),|native|empty.advance(native,4096,maximum,g));bank.normal(turn).unwrap();}
 assert!(empty.output_ready());let g=RetainedCloneGrant{maximum_copy_bytes:0,..bank.grant()};let turn=empty.take(g);let(value,p)=turn.result.unwrap().unwrap();assert_eq!(value,[]);bank.post(p,turn.work);empty.begin_close().unwrap();assert!(empty.terminal_is_empty());
}
